_KNOWLEDGE_FOLLOWUP = re.compile(
    r"^(?:그럼|그러면)(?:\s|[,，])|(?:^|\s)그\s+(?:논문|연구|자료|지표|방법|조건|부위|제품)"
    r"|(?:^|\s)(?:앞서|아까)\s*(?:말|언급|질문|본|보던)"
